-- ============================================================
-- Taste for Blood: wiring
-- ============================================================
--
-- TODO.md: "Improved Aspect of the Monkey (Renamed to Taste for Blood) (1, 1):
-- Redesigned. When attacking targets affected by Lacerating Shot your pet does
-- additional damage equal to 20/40/60% of your ranged attack power. (3 ranks)"
--
-- The retail talent's Effect1 was an ADD_FLAT_MODIFIER on the Aspect of the
-- Monkey / Dragonhawk dodge bonus; it becomes the spell_pet_auras carrier and
-- the store for the per-rank percentage.  Its class mask is explicitly zeroed --
-- a leftover mask on a DUMMY effect is harmless today but is exactly the kind of
-- thing a later `--base` clone inherits and silently mis-matches on.
--
-- One carrier (200745) serves all three ranks: the amount is read from the
-- owner's talent rank by OwnerTalentAmount, the spell_warl_demon_brutality
-- pattern (WarlockDemonPets.cpp:278).  Only chance-per-rank designs need one
-- carrier per rank, because spell_proc is keyed by spell id.
DELETE FROM `spell_pet_auras` WHERE `spell` IN (19549, 19550, 19551);
INSERT INTO `spell_pet_auras` (`spell`, `effectId`, `pet`, `aura`) VALUES
(19549, 0, 0, 200745),
(19550, 0, 0, 200745),
(19551, 0, 0, 200745);

-- ProcFlags 0x14 = PROC_FLAG_DONE_MELEE_AUTO_ATTACK (0x4)
--                | PROC_FLAG_DONE_SPELL_MELEE_DMG_CLASS (0x10)
-- so Claw/Bite/Gore count as well as white swings.  SpellPhaseMask 2 is
-- mandatory whenever 0x10 is present (SpellMgr.cpp:2113) and a zero there fails
-- silently.
--
-- Cooldown 1000 is a real design decision, not caution.  A cat at 1.0s swing
-- speed under Beast Cleave generates several proc events per second, and an
-- unthrottled 60%-of-RAP payload on each turns this talent into most of the
-- hunter's damage.  The ICD makes it a steady bonus rather than a haste scalar.
DELETE FROM `spell_proc` WHERE `SpellId` = 200745;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(200745, 0, 0, 0, 0, 0, 20, 0, 2, 0, 0, 0, 0, 100, 1000, 0);

-- 0x8000 = SPELL_ATTR0_CU_IGNORE_ARMOR (SpellInfo.h:192, loaded SpellMgr.cpp:3172).
-- The payload is a bleed echo scaled off ranged attack power, not a fresh
-- physical swing, so running it through Unit::IsDamageReducedByArmor would tax
-- it a second time on top of the parent hit that triggered it.  Same reasoning
-- as 200739.
DELETE FROM `spell_custom_attr` WHERE `spell_id` = 200746;
INSERT INTO `spell_custom_attr` (`spell_id`, `attributes`) VALUES
(200746, 0x8000);

